#!/bin/bash
set -e

# Write main.py which fully reimplements zoxide
cat << 'PYEOF' > main.py
#!/usr/bin/env python3
import sys, os, struct, time, base64, zlib, json, subprocess, shlex

def get_data_dir():
    d = os.environ.get("_ZO_DATA_DIR")
    if d: return d
    if sys.platform == "win32":
        return os.path.join(os.environ.get("LOCALAPPDATA", ""), "zoxide")
    elif sys.platform == "darwin":
        return os.path.expanduser("~/Library/Application Support/zoxide")
    else:
        return os.path.join(os.environ.get("XDG_DATA_HOME", os.path.expanduser("~/.local/share")), "zoxide")

db_path = os.path.join(get_data_dir(), "db.zo")

def load_db():
    if not os.path.exists(db_path): return []
    with open(db_path, "rb") as f: data = f.read()
    if len(data) < 12: return []
    try:
        version, count = struct.unpack("<IQ", data[:12])
        pos = 12
        entries = []
        for i in range(count):
            if pos + 8 > len(data): break
            path_len = struct.unpack("<Q", data[pos:pos+8])[0]
            pos += 8
            if pos + path_len > len(data): break
            path = data[pos:pos+path_len].decode("utf-8", "replace")
            pos += path_len
            if pos + 16 > len(data): break
            score, ts = struct.unpack("<dq", data[pos:pos+16])
            pos += 16
            entries.append({"path": path, "score": score, "time": ts, "idx": i})
        return entries
    except Exception:
        return []

def save_db(entries):
    os.makedirs(os.path.dirname(db_path), exist_ok=True)
    out = bytearray(struct.pack("<IQ", 3, len(entries)))
    for e in entries:
        p = e["path"].encode("utf-8")
        out.extend(struct.pack("<Q", len(p)))
        out.extend(p)
        out.extend(struct.pack("<dq", float(e["score"]), int(e["time"])))
    with open(db_path, "wb") as f:
        f.write(out)

def do_aging(entries, max_age):
    total = sum(e["score"] for e in entries)
    if total > max_age:
        factor = (max_age * 0.9) / total
        new_entries = []
        for e in entries:
            e["score"] *= factor
            if e["score"] >= 1.0:
                new_entries.append(e)
        return new_entries
    return entries

def cmd_add(paths):
    max_age = int(os.environ.get("_ZO_MAXAGE", "10000"))
    resolve = os.environ.get("_ZO_RESOLVE_SYMLINKS", "0") == "1"
    resolved_paths = []
    for p in paths:
        rp = os.path.realpath(p) if resolve else os.path.abspath(p)
        if not os.path.isdir(rp):
            print(f"zoxide: not a directory: {p}", file=sys.stderr)
            sys.exit(1)
        resolved_paths.append(rp)
    entries = load_db()
    now = int(time.time())
    for rp in resolved_paths:
        found = False
        for e in entries:
            if e["path"] == rp:
                e["score"] += 1.0
                e["time"] = now
                found = True
                break
        if not found:
            entries.append({"path": rp, "score": 1.0, "time": now, "idx": len(entries)})
    entries = do_aging(entries, max_age)
    save_db(entries)

def calc_frecency(score, ts, now):
    dt = max(0, now - ts)
    if dt < 3600: return score * 4.0
    if dt < 86400: return score * 2.0
    if dt < 604800: return score * 0.5
    return score * 0.25

def match_path(path, keywords):
    if not keywords: return True
    path_lower = path.lower()
    idx = 0
    for kw in keywords:
        kw_lower = kw.lower()
        idx = path_lower.find(kw_lower, idx)
        if idx == -1: return False
        idx += len(kw)
    last_kw = keywords[-1]
    if not last_kw.endswith('/'):
        basename = path.rsplit('/', 1)[-1].lower()
        if last_kw.lower() not in basename:
            return False
    return True

def cmd_query(args):
    opts = {"all": False, "interactive": False, "list": False, "score": False, "exclude": None, "base_dir": None}
    keywords, i = [], 0
    while i < len(args):
        a = args[i]
        if a in ("-a", "--all"): opts["all"] = True
        elif a in ("-i", "--interactive"): opts["interactive"] = True
        elif a in ("-l", "--list"): opts["list"] = True
        elif a in ("-s", "--score"): opts["score"] = True
        elif a == "--exclude":
            opts["exclude"] = args[i+1]
            i += 1
        elif a == "--base-dir":
            opts["base_dir"] = args[i+1]
            i += 1
        elif not a.startswith('-'):
            keywords.append(a)
        i += 1
    entries = load_db()
    now = int(time.time())
    matches = []
    for e in entries:
        e["frecency"] = calc_frecency(e["score"], e["time"], now)
        if opts["base_dir"] and not e["path"].startswith(opts["base_dir"]): continue
        if not opts["all"] and not os.path.isdir(e["path"]): continue
        if not match_path(e["path"], keywords): continue
        matches.append(e)
    matches.sort(key=lambda x: (x["frecency"], x["idx"]), reverse=True)

    would_have_matched_exclude = False
    if opts["exclude"]:
        ex_path = opts["exclude"]
        new_matches = []
        for m in matches:
            if m["path"] == ex_path:
                would_have_matched_exclude = True
            else:
                new_matches.append(m)
        matches = new_matches

    if not matches:
        if would_have_matched_exclude:
            print("zoxide: you are already in the only match", file=sys.stderr)
        else:
            print("zoxide: no match found", file=sys.stderr)
        sys.exit(1)

    if opts["interactive"]:
        import shutil
        if not shutil.which("fzf"):
            print("zoxide: could not find fzf, is it installed?", file=sys.stderr)
            sys.exit(1)
        fzf_input = "".join(f"{m['frecency']:>6.1f}\t{m['path']}\0" for m in matches)
        fzf_cmd = ["fzf", "--delimiter=\\t", "--nth=2", "--read0", "--exact", "--no-sort",
                   "--bind=ctrl-z:ignore,btab:up,tab:down", "--cycle", "--keep-right",
                   "--border=sharp", "--height=45%", "--info=inline", "--layout=reverse",
                   "--tabstop=1", "--exit-0", "--preview=\\command -p ls -Cp --color=always --group-directories-first {2..}",
                   "--preview-window=down,30%,sharp"]
        fopts = os.environ.get("_ZO_FZF_OPTS")
        if fopts: fzf_cmd.extend(shlex.split(fopts))
        try:
            res = subprocess.run(fzf_cmd, input=fzf_input.encode('utf-8'), capture_output=True)
            if res.returncode != 0: sys.exit(res.returncode)
            out = res.stdout.decode('utf-8').strip()
            if '\t' in out: print(out.split('\t', 1)[1])
        except Exception:
            sys.exit(1)
        return

    if opts["list"]:
        for m in matches:
            if opts["score"]: print(f"{m['frecency']:>6.1f} {m['path']}")
            else: print(m['path'])
    else:
        print(matches[0]['path'])

def cmd_remove(paths):
    entries = load_db()
    to_remove = set()
    for p in paths:
        if not any(e["path"] == p for e in entries):
            print(f"zoxide: path not found in database: {p}", file=sys.stderr)
            sys.exit(1)
        to_remove.add(p)
    save_db([e for e in entries if e["path"] not in to_remove])

def cmd_init(args):
    shell = ""
    cmd = "z"
    hook = "pwd"
    no_cmd = False
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--cmd":
            cmd = args[i+1]
            i += 1
        elif a == "--hook":
            hook = args[i+1]
            i += 1
        elif a == "--no-cmd":
            no_cmd = True
        elif not a.startswith('-'):
            shell = a
        i += 1
    key = f"{hook}_{no_cmd}"
    with open(os.path.join(os.path.dirname(__file__), "templates_b64.txt")) as f:
        b64 = f.read()
    templates = json.loads(zlib.decompress(base64.b64decode(b64)).decode('utf-8'))
    if shell in templates and key in templates[shell]:
        out = templates[shell][key].replace("ZCMDXYZi", cmd + "i").replace("ZCMDXYZ", cmd)
        print(out, end='')

def cmd_edit(args):
    import shutil
    if not shutil.which("fzf"):
        print("zoxide: could not find fzf, is it installed?", file=sys.stderr)
        sys.exit(1)
    if args and args[0] in ("delete", "increment", "decrement", "reload"):
        action = args[0]
        paths = args[1:]
        entries = load_db()
        now = int(time.time())
        if action == "delete":
            entries = [e for e in entries if e["path"] not in paths]
        elif action == "increment":
            for e in entries:
                if e["path"] in paths:
                    e["score"] += 1.0
                    e["time"] = now
        elif action == "decrement":
            for e in entries:
                if e["path"] in paths:
                    e["score"] = max(0.0, e["score"] - 1.0)
        save_db(entries)
        if action != "delete":
            entries = load_db()
        for e in entries:
            e["frecency"] = calc_frecency(e["score"], e["time"], now)
        entries.sort(key=lambda x: (x["frecency"], x["idx"]), reverse=True)
        print("".join(f"{e['frecency']:>6.1f}\t{e['path']}\0" for e in entries), end="")
        return
    entries = load_db()
    now = int(time.time())
    for e in entries:
        e["frecency"] = calc_frecency(e["score"], e["time"], now)
    entries.sort(key=lambda x: (x["frecency"], x["idx"]), reverse=True)
    fzf_input = "".join(f"{e['frecency']:>6.1f}\t{e['path']}\0" for e in entries)
    cname = sys.argv[0]
    fzf_cmd = ["fzf", "--delimiter=\\t", "--nth=2", "--read0", "--exact", "--no-sort",
               f"--bind=btab:up,ctrl-r:reload({cname} edit reload),ctrl-d:reload({cname} edit delete {{2..}}),ctrl-w:reload({cname} edit increment {{2..}}),ctrl-s:reload({cname} edit decrement {{2..}}),ctrl-z:ignore,double-click:ignore,enter:abort,start:reload({cname} edit reload),tab:down",
               "--cycle", "--keep-right", "--border=sharp", "--border-label=  zoxide-edit  ",
               "--header=ctrl-r:reload   \tctrl-d:delete\nctrl-w:increment\tctrl-s:decrement\n\n SCORE\tPATH",
               "--info=inline", "--layout=reverse", "--padding=1,0,0,0", "--color=label:bold", "--tabstop=1",
               "--preview=\\command -p ls -Cp --color=always --group-directories-first {2..}", "--preview-window=down,30%,sharp"]
    fopts = os.environ.get("_ZO_FZF_OPTS")
    if fopts: fzf_cmd.extend(shlex.split(fopts))
    try: subprocess.run(fzf_cmd, input=fzf_input.encode('utf-8'))
    except Exception: pass

def cmd_import(args):
    from_app, merge, path = "z", False, ""
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--from":
            from_app = args[i+1]
            i += 1
        elif a == "--merge": merge = True
        elif not a.startswith('-'): path = a
        i += 1
    entries = load_db()
    if entries and not merge:
        print("zoxide: current database is not empty, specify --merge to continue anyway", file=sys.stderr)
        sys.exit(1)
    try:
        with open(path, "r") as f: lines = f.readlines()
        for line in lines:
            line = line.strip()
            if not line: continue
            if from_app == "z":
                parts = line.split('|')
                if len(parts) >= 3:
                    entries.append({"path": parts[0], "score": float(parts[1]), "time": int(parts[2]), "idx": len(entries)})
            elif from_app == "autojump":
                parts = line.split('\t')
                if len(parts) >= 2:
                    entries.append({"path": parts[1], "score": float(parts[0]), "time": 0, "idx": len(entries)})
        save_db(entries)
    except Exception:
        pass

def print_help(cmd):
    with open(os.path.join(os.path.dirname(__file__), "helps_b64.txt")) as f:
        b64 = f.read()
    d = json.loads(zlib.decompress(base64.b64decode(b64)).decode('utf-8'))
    print(d.get(cmd, d[""]), end="")

def main():
    if len(sys.argv) > 1 and sys.argv[1] in ("-h", "--help"):
        print_help("")
        sys.exit(0)
    elif len(sys.argv) > 1 and sys.argv[1] in ("-V", "--version"):
        print("zoxide 0.9.9\n")
        sys.exit(0)
    if len(sys.argv) < 2:
        print_help("")
        sys.exit(0)
    cmd = sys.argv[1]
    if "-h" in sys.argv or "--help" in sys.argv:
        print_help(cmd)
        sys.exit(0)
    if cmd == "add": cmd_add(sys.argv[2:])
    elif cmd == "query": cmd_query(sys.argv[2:])
    elif cmd == "remove": cmd_remove(sys.argv[2:])
    elif cmd == "init": cmd_init(sys.argv[2:])
    elif cmd == "import": cmd_import(sys.argv[2:])
    elif cmd == "edit": cmd_edit(sys.argv[2:])
    else:
        print_help("")
        sys.exit(1)

if __name__ == "__main__":
    main()
